1	package com.example.starter.service;
2	
3	import com.example.starter.domain.JobStatus;
4	import com.example.starter.domain.TestResult;
5	import com.example.starter.domain.TestType;
6	import com.example.starter.repo.BrakeTestRepository;
7	import com.example.starter.repo.BrakeTestRow;
8	import com.example.starter.repo.ConsistCheckRepository;
9	import com.example.starter.repo.JobRow;
10	import com.example.starter.repo.PressureReadingRepository;
11	import com.example.starter.repo.CarRow;
12	import com.example.starter.repo.TrainCarRepository;
13	import com.example.starter.repo.TrainJobRepository;
14	import com.example.starter.web.dto.AcceptJobRequest;
15	import com.example.starter.web.dto.BrakeTestRequest;
16	import com.example.starter.web.dto.BrakeTestResponse;
17	import com.example.starter.web.dto.CarDto;
18	import com.example.starter.web.dto.ClosedCarListResponse;
19	import com.example.starter.web.dto.ClosureResponse;
20	import com.example.starter.web.dto.ConsistChangeRequest;
21	import com.example.starter.web.dto.ConsistChangeResponse;
22	import com.example.starter.web.dto.ConsistCheckRequest;
23	import com.example.starter.web.dto.ConsistCheckResponse;
24	import com.example.starter.web.dto.ConsistResponse;
25	import com.example.starter.web.dto.DepartureResponse;
26	import com.example.starter.web.dto.JobResponse;
27	import com.example.starter.web.dto.PressureReadingRequest;
28	import com.example.starter.web.dto.PressureReadingResponse;
29	import com.example.starter.web.dto.RequestIdOnly;
30	import com.example.starter.web.dto.TestCurveResponse;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.annotation.Transactional;
34	
35	import java.math.BigDecimal;
36	import java.util.List;
37	
38	/**
39	 * 列车制动机试验与摘挂核对核心服务。
40	 * 流程：接入 → 摘挂 → 编组核对 → 制动试验（感度/安定） → 发车确认 → 销记终态。
41	 */
42	@Service
43	public class TrainJobService {
44	
45	    /** 列车管定压，单位 kPa；两项试验之间须恢复至定压，恰达定压允许下一项。 */
46	    public static final int RATED_PRESSURE_KPA = 500;
47	    /** 感度试验减压量，单位 kPa。 */
48	    public static final int SENSITIVITY_REDUCTION_KPA = 50;
49	    /** 安定试验减压量，单位 kPa；恰 140kPa 合格。 */
50	    public static final int STABILITY_REDUCTION_KPA = 140;
51	    /** 关门车比例上限分子（6%），恰 6% 合法。 */
52	    public static final int CLOSED_CAR_LIMIT_PERCENT = 6;
53	
54	    private final TrainJobRepository jobRepository;
55	    private final TrainCarRepository carRepository;
56	    private final BrakeTestRepository brakeTestRepository;
57	    private final ConsistCheckRepository consistCheckRepository;
58	    private final PressureReadingRepository pressureReadingRepository;
59	    private final IdempotencyService idempotencyService;
60	
61	    public TrainJobService(TrainJobRepository jobRepository, TrainCarRepository carRepository,
62	                           BrakeTestRepository brakeTestRepository,
63	                           ConsistCheckRepository consistCheckRepository,
64	                           PressureReadingRepository pressureReadingRepository,
65	                           IdempotencyService idempotencyService) {
66	        this.jobRepository = jobRepository;
67	        this.carRepository = carRepository;
68	        this.brakeTestRepository = brakeTestRepository;
69	        this.consistCheckRepository = consistCheckRepository;
70	        this.pressureReadingRepository = pressureReadingRepository;
71	        this.idempotencyService = idempotencyService;
72	    }
73	
74	    /**
75	     * 接入列车作业；同一股道同时刻仅允许一列作业中列车，并发接入唯一受理。
76	     */
77	    public JobResponse accept(AcceptJobRequest request) {
78	        return idempotencyService.execute(request.requestId(), "ACCEPT", request,
79	                JobResponse.class, () -> doAccept(request));
80	    }
81	
82	    /**
83	     * 摘挂变更；变更与试验结论作废在同一事务内完成，变更后须重新核对与重做试验。
84	     */
85	    public ConsistChangeResponse changeConsist(long jobId, ConsistChangeRequest request) {
86	        return idempotencyService.execute(request.requestId(), "CONSIST_CHANGE", request,
87	                ConsistChangeResponse.class, () -> doChangeConsist(jobId, request));
88	    }
89	
90	    /**
91	     * 编组核对：辆数、换长、总重与合成运统1比对，不一致则拒绝后续发车。
92	     */
93	    public ConsistCheckResponse checkConsist(long jobId, ConsistCheckRequest request) {
94	        return idempotencyService.execute(request.requestId(), "CONSIST_CHECK", request,
95	                ConsistCheckResponse.class, () -> doCheckConsist(jobId, request));
96	    }
97	
98	    /**
99	     * 制动试验：感度减压 50kPa 全列须制动；安定减压 140kPa 不得紧急制动；
100	     * 两项之间风压须恢复至定压 500kPa（恰达允许）。
101	     */
102	    public BrakeTestResponse brakeTest(long jobId, BrakeTestRequest request) {
103	        return idempotencyService.execute(request.requestId(), "BRAKE_TEST", request,
104	                BrakeTestResponse.class, () -> doBrakeTest(jobId, request));
105	    }
106	
107	    /**
108	     * 发车确认：运统1核对一致、感度与安定均合格、关门车比例不超限方可发车。
109	     */
110	    public DepartureResponse confirmDeparture(long jobId, RequestIdOnly request) {
111	        return idempotencyService.execute(request.requestId(), "DEPARTURE", request,
112	                DepartureResponse.class, () -> doConfirmDeparture(jobId));
113	    }
114	
115	    /**
116	     * 销记：终态；重复销记返回幂等成功。
117	     */
118	    public ClosureResponse close(long jobId, RequestIdOnly request) {
119	        return idempotencyService.execute(request.requestId(), "CLOSURE", request,
120	                ClosureResponse.class, () -> doClose(jobId));
121	    }
122	
123	    /**
124	     * 风压读数上报；销记后迟到数据只记迟到事件。
125	     */
126	    public PressureReadingResponse reportPressure(long jobId, PressureReadingRequest request) {
127	        return idempotencyService.execute(request.requestId(), "PRESSURE", request,
128	                PressureReadingResponse.class, () -> doReportPressure(jobId, request));
129	    }
130	
131	    private JobResponse doAccept(AcceptJobRequest request) {
132	        List<CarDto> cars = request.cars();
133	        checkClosedCarRatio(cars);
134	        BigDecimal totalLength = cars.stream().map(CarDto::length).reduce(BigDecimal.ZERO, BigDecimal::add);
135	        BigDecimal totalWeight = cars.stream().map(CarDto::weightTons).reduce(BigDecimal.ZERO, BigDecimal::add);
136	        long jobId;
137	        try {
138	            jobId = jobRepository.insert(request.trainNo(), request.track(),
139	                    cars.size(), totalLength, totalWeight);
140	        } catch (DuplicateKeyException e) {
141	            throw new ConflictException("同一股道同时刻仅允许一列作业中列车：" + request.track());
142	        }
143	        for (int i = 0; i < cars.size(); i++) {
144	            carRepository.insert(jobId, i + 1, cars.get(i));
145	        }
146	        return toJobResponse(jobRepository.findById(jobId).orElseThrow());
147	    }
148	
149	    private ConsistChangeResponse doChangeConsist(long jobId, ConsistChangeRequest request) {
150	        JobRow job = requireJob(jobId);
151	        if (job.status() != JobStatus.ACCEPTED && job.status() != JobStatus.CHECKED) {
152	            throw new BusinessException("当前状态不允许摘挂变更：" + job.status());
153	        }
154	        for (String carNo : request.detachCarNos()) {
155	            if (!carRepository.detach(jobId, carNo)) {
156	                throw new BusinessException("摘车失败，车辆不存在或已摘下：" + carNo);
157	            }
158	        }
159	        int nextSeq = carRepository.findActiveByJobId(jobId).size();
160	        for (CarDto car : request.attachCars()) {
161	            List<CarRow> existing = carRepository.findByJobIdAndCarNo(jobId, car.carNo());
162	            if (!existing.isEmpty()) {
163	                if (existing.get(0).detached()) {
164	                    nextSeq++;
165	                    carRepository.reattach(jobId, car.carNo(), nextSeq);
166	                } else {
167	                    throw new BusinessException("挂车失败，车辆已在列：" + car.carNo());
168	                }
169	            } else {
170	                nextSeq++;
171	                carRepository.insert(jobId, nextSeq, car);
172	            }
173	        }
174	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
175	        if (active.isEmpty()) {
176	            throw new BusinessException("摘挂后在列辆数不得为空");
177	        }
178	        checkClosedCarRatio(active.stream()
179	                .map(c -> new CarDto(c.carNo(), c.weightTons(), c.length(), c.valveClosed()))
180	                .toList());
181	        int voidedTests = brakeTestRepository.voidAllByJobId(jobId);
182	        BigDecimal totalLength = active.stream().map(CarRow::length).reduce(BigDecimal.ZERO, BigDecimal::add);
183	        BigDecimal totalWeight = active.stream().map(CarRow::weightTons).reduce(BigDecimal.ZERO, BigDecimal::add);
184	        int newVersion = job.consistVersion() + 1;
185	        jobRepository.updateConsist(jobId, newVersion, active.size(), totalLength, totalWeight,
186	                false, JobStatus.ACCEPTED);
187	        return new ConsistChangeResponse(jobId, newVersion, active.size(), totalLength, totalWeight, voidedTests);
188	    }
189	
190	    private ConsistCheckResponse doCheckConsist(long jobId, ConsistCheckRequest request) {
191	        JobRow job = requireJob(jobId);
192	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
193	            throw new BusinessException("当前状态不允许编组核对：" + job.status());
194	        }
195	        boolean matched = request.expectedCarCount() == job.carCount()
196	                && request.expectedTotalLength().compareTo(job.totalLength()) == 0
197	                && request.expectedTotalWeight().compareTo(job.totalWeight()) == 0;
198	        long checkId = consistCheckRepository.insert(jobId, job.consistVersion(),
199	                request.expectedCarCount(), request.expectedTotalLength(), request.expectedTotalWeight(),
200	                job.carCount(), job.totalLength(), job.totalWeight(), matched, request.requestId());
201	        jobRepository.updateStatusAndChecked(jobId,
202	                matched ? JobStatus.CHECKED : JobStatus.ACCEPTED, matched);
203	        String message = matched ? "编组与运统1一致" : "编组与运统1不一致，拒绝发车";
204	        return new ConsistCheckResponse(checkId, matched, job.consistVersion(),
205	                request.expectedCarCount(), job.carCount(),
206	                request.expectedTotalLength(), job.totalLength(),
207	                request.expectedTotalWeight(), job.totalWeight(), message);
208	    }
209	
210	    private BrakeTestResponse doBrakeTest(long jobId, BrakeTestRequest request) {
211	        JobRow job = requireJob(jobId);
212	        if (job.status() != JobStatus.CHECKED) {
213	            throw new BusinessException("编组未通过运统1核对或状态不允许试验：" + job.status());
214	        }
215	        if (request.pipePressureBefore() < RATED_PRESSURE_KPA) {
216	            throw new BusinessException("风压未恢复至定压 " + RATED_PRESSURE_KPA + "kPa，不得进行试验");
217	        }
218	        TestResult result;
219	        String message;
220	        if (request.testType() == TestType.SENSITIVITY) {
221	            if (request.pressureReduction() != SENSITIVITY_REDUCTION_KPA) {
222	                throw new BusinessException("感度试验减压量须为 " + SENSITIVITY_REDUCTION_KPA + "kPa");
223	            }
224	            if (request.allCarsBraked() == null) {
225	                throw new BusinessException("感度试验须上报全列制动情况");
226	            }
227	            result = request.allCarsBraked() ? TestResult.PASS : TestResult.FAIL;
228	            message = result == TestResult.PASS ? "感度试验合格" : "感度试验不合格：存在未制动车辆";
229	        } else {
230	            requireSensitivityPassed(job);
231	            if (request.pressureReduction() != STABILITY_REDUCTION_KPA) {
232	                throw new BusinessException("安定试验减压量须为 " + STABILITY_REDUCTION_KPA + "kPa");
233	            }
234	            if (request.emergencyOccurred() == null) {
235	                throw new BusinessException("安定试验须上报紧急制动情况");
236	            }
237	            result = request.emergencyOccurred() ? TestResult.FAIL : TestResult.PASS;
238	            message = result == TestResult.PASS ? "安定试验合格" : "安定试验不合格：发生紧急制动";
239	        }
240	        long testId = brakeTestRepository.insert(jobId, job.consistVersion(), request.testType(),
241	                request.pressureReduction(), request.pipePressureBefore(),
242	                request.allCarsBraked(), request.emergencyOccurred(), result, request.requestId());
243	        return new BrakeTestResponse(testId, request.testType().name(), result.name(),
244	                job.consistVersion(), message);
245	    }
246	
247	    private DepartureResponse doConfirmDeparture(long jobId) {
248	        JobRow job = requireJob(jobId);
249	        if (job.status() == JobStatus.CLOSED) {
250	            throw new BusinessException("作业已销记，不得重复发车确认");
251	        }
252	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED) {
253	            return new DepartureResponse(jobId, true, "已确认发车");
254	        }
255	        if (!job.consistChecked()) {
256	            throw new BusinessException("编组与运统1不一致或未核对，拒绝发车");
257	        }
258	        requirePassed(job, TestType.SENSITIVITY);
259	        requirePassed(job, TestType.STABILITY);
260	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
261	        long closed = active.stream().filter(CarRow::valveClosed).count();
262	        if (!withinClosedCarLimit(closed, active.size())) {
263	            throw new BusinessException("关门车比例超过 6%，拒绝发车");
264	        }
265	        jobRepository.updateStatus(jobId, JobStatus.DEPARTURE_CONFIRMED);
266	        return new DepartureResponse(jobId, true, "准许发车");
267	    }
268	
269	    private ClosureResponse doClose(long jobId) {
270	        JobRow job = requireJob(jobId);
271	        if (job.status() == JobStatus.CLOSED) {
272	            return new ClosureResponse(jobId, true, true, "重复销记，幂等成功");
273	        }
274	        if (job.status() != JobStatus.DEPARTURE_CONFIRMED) {
275	            throw new BusinessException("未发车确认，不得销记：" + job.status());
276	        }
277	        jobRepository.close(jobId);
278	        return new ClosureResponse(jobId, true, false, "销记完成，作业终态");
279	    }
280	
281	    private PressureReadingResponse doReportPressure(long jobId, PressureReadingRequest request) {
282	        JobRow job = requireJob(jobId);
283	        if (job.status() == JobStatus.CLOSED) {
284	            pressureReadingRepository.insertLateEvent(jobId, "LATE_PRESSURE",
285	                    "销记后迟到风压数据：" + request.pressure() + "kPa，采集时间 " + request.recordedAt());
286	            return new PressureReadingResponse(null, false, true, "作业已销记，迟到数据仅记迟到事件");
287	        }
288	        long readingId = pressureReadingRepository.insert(jobId, request.pressure(),
289	                request.recordedAt(), false, request.requestId());
290	        return new PressureReadingResponse(readingId, true, false, "风压读数已记录");
291	    }
292	
293	    /**
294	     * 查询作业视图。
295	     */
296	    @Transactional(readOnly = true)
297	    public JobResponse getJob(long jobId) {
298	        return toJobResponse(requireJob(jobId));
299	    }
300	
301	    /**
302	     * 复算试验曲线：风压读数（不含迟到数据）与试验事件。
303	     */
304	    @Transactional(readOnly = true)
305	    public TestCurveResponse getTestCurve(long jobId) {
306	        requireJob(jobId);
307	        List<TestCurveResponse.TestPoint> tests = brakeTestRepository.findByJobId(jobId).stream()
308	                .map(t -> new TestCurveResponse.TestPoint(t.testType().name(), t.pressureReduction(),
309	                        t.result().name(), t.consistVersion(), t.voided(), t.createdAt()))
310	                .toList();
311	        return new TestCurveResponse(jobId, pressureReadingRepository.findCurvePoints(jobId), tests);
312	    }
313	
314	    /**
315	     * 复算关门车清单与比例。
316	     */
317	    @Transactional(readOnly = true)
318	    public ClosedCarListResponse getClosedCars(long jobId) {
319	        requireJob(jobId);
320	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
321	        List<String> closedNos = active.stream().filter(CarRow::valveClosed).map(CarRow::carNo).toList();
322	        double ratio = active.isEmpty() ? 0.0 : (double) closedNos.size() / active.size();
323	        return new ClosedCarListResponse(jobId, closedNos, closedNos.size(), active.size(), ratio,
324	                withinClosedCarLimit(closedNos.size(), active.size()));
325	    }
326	
327	    /**
328	     * 复算当前编组版本与在列车辆。
329	     */
330	    @Transactional(readOnly = true)
331	    public ConsistResponse getConsist(long jobId) {
332	        JobRow job = requireJob(jobId);
333	        List<ConsistResponse.CarView> cars = carRepository.findActiveByJobId(jobId).stream()
334	                .map(c -> new ConsistResponse.CarView(c.carNo(), c.seqNo(), c.weightTons(),
335	                        c.length(), c.valveClosed()))
336	                .toList();
337	        return new ConsistResponse(jobId, job.consistVersion(), job.carCount(),
338	                job.totalLength(), job.totalWeight(), cars);
339	    }
340	
341	    private JobRow requireJob(long jobId) {
342	        return jobRepository.findById(jobId)
343	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
344	    }
345	
346	    private void requireSensitivityPassed(JobRow job) {
347	        requirePassed(job, TestType.SENSITIVITY);
348	    }
349	
350	    private void requirePassed(JobRow job, TestType testType) {
351	        BrakeTestRow latest = brakeTestRepository
352	                .findLatestActive(job.id(), job.consistVersion(), testType)
353	                .orElseThrow(() -> new BusinessException("当前编组版本未完成" + testType + "试验"));
354	        if (latest.result() != TestResult.PASS) {
355	            throw new BusinessException("当前编组版本" + testType + "试验不合格");
356	        }
357	    }
358	
359	    private void checkClosedCarRatio(List<CarDto> cars) {
360	        long closed = cars.stream().filter(CarDto::valveClosed).count();
361	        if (!withinClosedCarLimit(closed, cars.size())) {
362	            throw new BusinessException("关门车比例超过 6%：" + closed + "/" + cars.size());
363	        }
364	    }
365	
366	    private boolean withinClosedCarLimit(long closed, long total) {
367	        return total > 0 && closed * 100 <= total * CLOSED_CAR_LIMIT_PERCENT;
368	    }
369	
370	    private JobResponse toJobResponse(JobRow job) {
371	        List<CarRow> active = carRepository.findActiveByJobId(job.id());
372	        long closed = active.stream().filter(CarRow::valveClosed).count();
373	        double ratio = active.isEmpty() ? 0.0 : (double) closed / active.size();
374	        return new JobResponse(job.id(), job.trainNo(), job.track(), job.status().name(),
375	                job.consistVersion(), job.carCount(), job.totalLength(), job.totalWeight(),
376	                (int) closed, ratio);
377	    }
378	}
