215	    void 同一股道并发接入唯一受理() throws Exception {
216	        int threads = 4;
217	        ExecutorService pool = Executors.newFixedThreadPool(threads);
218	        CountDownLatch ready = new CountDownLatch(threads);
219	        CountDownLatch start = new CountDownLatch(1);
220	        AtomicInteger success = new AtomicInteger();
221	        AtomicInteger conflict = new AtomicInteger();
222	        List<Future<?>> futures = new ArrayList<>();
223	        for (int i = 0; i < threads; i++) {
224	            int idx = i;
225	            futures.add(pool.submit(() -> {
226	                ready.countDown();
227	                try {
228	                    start.await(5, TimeUnit.SECONDS);
229	                    service.accept(acceptRequest("k9-" + idx, "G10", 10, 0));
230	                    success.incrementAndGet();
231	                } catch (ConflictException e) {
232	                    conflict.incrementAndGet();
233	                } catch (Exception e) {
234	                    throw new RuntimeException(e);
235	                }
236	            }));
237	        }
238	        assertTrue(ready.await(5, TimeUnit.SECONDS));
239	        start.countDown();
240	        for (Future<?> future : futures) {
241	            future.get(15, TimeUnit.SECONDS);
242	        }
243	        pool.shutdownNow();
244	        assertEquals(1, success.get());
245	        assertEquals(threads - 1, conflict.get());
246	        Integer jobs = jdbc.queryForObject("SELECT COUNT(*) FROM train_job WHERE track = 'G10'",
247	                Integer.class);
