    @Test
    void 试验前未核对运统1拒绝试验() {
        JobResponse job = service.accept(acceptRequest("k16-a", "G17", 10, 0));
        assertThrows(BusinessException.class,
                () -> service.brakeTest(job.id(), sensitivity("k16-s", 50, 500, true)));
    }

    @Test
