17	 */
18	@Repository
19	public class BrakeTestRepository {
20	
21	    private static final RowMapper<BrakeTestRow> ROW_MAPPER = (rs, n) -> new BrakeTestRow(
22	            rs.getLong("id"),
23	            rs.getLong("job_id"),
24	            rs.getInt("consist_version"),
25	            TestType.valueOf(rs.getString("test_type")),
26	            rs.getInt("pressure_reduction"),
27	            rs.getInt("pipe_pressure_before"),
28	            TestResult.valueOf(rs.getString("result")),
29	            rs.getBoolean("voided"),
30	            rs.getTimestamp("created_at").toLocalDateTime());
31	
32	    private final JdbcTemplate jdbc;
33	
34	    public BrakeTestRepository(JdbcTemplate jdbc) {
35	        this.jdbc = jdbc;
36	    }
37	
38	    /**
39	     * 记录试验结论。
40	     */
41	    public long insert(long jobId, int consistVersion, TestType testType, int pressureReduction,
42	                       int pipePressureBefore, Boolean allCarsBraked, Boolean emergencyOccurred,
43	                       TestResult result, String requestId) {
44	        KeyHolder keyHolder = new GeneratedKeyHolder();
45	        jdbc.update(con -> {
46	            PreparedStatement ps = con.prepareStatement(
47	                    "INSERT INTO brake_test (job_id, consist_version, test_type, pressure_reduction,"
48	                            + " pipe_pressure_before, all_cars_braked, emergency_occurred, result, voided,"
49	                            + " request_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, FALSE, ?, CURRENT_TIMESTAMP)",
50	                    new String[]{"id"});
51	            ps.setLong(1, jobId);
52	            ps.setInt(2, consistVersion);
53	            ps.setString(3, testType.name());
54	            ps.setInt(4, pressureReduction);
55	            ps.setInt(5, pipePressureBefore);
56	            if (allCarsBraked == null) {
57	                ps.setNull(6, java.sql.Types.BOOLEAN);
58	            } else {
59	                ps.setBoolean(6, allCarsBraked);
60	            }
61	            if (emergencyOccurred == null) {
62	                ps.setNull(7, java.sql.Types.BOOLEAN);
63	            } else {
64	                ps.setBoolean(7, emergencyOccurred);
65	            }
66	            ps.setString(8, result.name());
67	            ps.setString(9, requestId);
68	            return ps;
69	        }, keyHolder);
70	        return keyHolder.getKey().longValue();
71	    }
72	
73	    /**
74	     * 作废作业全部未作废试验结论（编组变更同事务调用）；返回作废条数。
75	     */
76	    public int voidAllByJobId(long jobId) {
77	        return jdbc.update("UPDATE brake_test SET voided = TRUE WHERE job_id = ? AND voided = FALSE", jobId);
78	    }
79	
80	    /**
81	     * 查询当前编组版本下指定类型的最新有效试验结论。
82	     */
83	    public Optional<BrakeTestRow> findLatestActive(long jobId, int consistVersion, TestType testType) {
84	        return jdbc.query("SELECT * FROM brake_test WHERE job_id = ? AND consist_version = ?"
85	                        + " AND test_type = ? AND voided = FALSE ORDER BY id DESC LIMIT 1",
86	                ROW_MAPPER, jobId, consistVersion, testType.name()).stream().findFirst();
87	    }
88	
89	    /**
90	     * 查询作业全部试验记录（试验曲线复算用）。
91	     */
92	    public List<BrakeTestRow> findByJobId(long jobId) {
93	        return jdbc.query("SELECT * FROM brake_test WHERE job_id = ? ORDER BY id", ROW_MAPPER, jobId);
94	    }
95	}
