package com.example.starter.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.Optional;

/**
 * 列尾装置台账数据访问；自检截止时刻按 UTC 存取。
 */
@Repository
public class TailDeviceRepository {

    private static final RowMapper<TailDeviceRow> ROW_MAPPER = (rs, n) -> new TailDeviceRow(
            rs.getString("device_no"),
            rs.getTimestamp("self_check_expires_at").toLocalDateTime().toInstant(ZoneOffset.UTC),
            rs.getObject("current_binding_id", Long.class),
            rs.getInt("version"));

    private final JdbcTemplate jdbc;

    public TailDeviceRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 装置建档，初始版本为1、空闲。
     */
    public void insert(String deviceNo, Instant selfCheckExpiresAt) {
        jdbc.update("INSERT INTO tail_device (device_no, self_check_expires_at, current_binding_id,"
                        + " version, created_at, updated_at) VALUES (?, ?, NULL, 1,"
                        + " CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)",
                deviceNo, Timestamp.valueOf(LocalDateTime.ofInstant(selfCheckExpiresAt, ZoneOffset.UTC)));
    }

    /**
     * 按编号查询装置。
     */
    public Optional<TailDeviceRow> findByDeviceNo(String deviceNo) {
        return jdbc.query("SELECT * FROM tail_device WHERE device_no = ?", ROW_MAPPER, deviceNo)
                .stream().findFirst();
    }

    /**
     * 按编号查询并加行锁（事务内串行化绑定/释放/换发）。
     */
    public Optional<TailDeviceRow> findByDeviceNoForUpdate(String deviceNo) {
        return jdbc.query("SELECT * FROM tail_device WHERE device_no = ? FOR UPDATE", ROW_MAPPER, deviceNo)
                .stream().findFirst();
    }

    /**
     * 占用装置：仅当装置空闲且版本匹配时成功（并发绑定唯一成功的原子保证）。
     *
     * @return 是否占用成功
     */
    public boolean occupy(String deviceNo, long bindingId, int expectedVersion) {
        return jdbc.update("UPDATE tail_device SET current_binding_id = ?, version = version + 1,"
                        + " updated_at = CURRENT_TIMESTAMP"
                        + " WHERE device_no = ? AND current_binding_id IS NULL AND version = ?",
                bindingId, deviceNo, expectedVersion) > 0;
    }

    /**
     * 释放装置占用：仅当当前占用为指定绑定且版本匹配时成功。
     *
     * @return 是否释放成功
     */
    public boolean release(String deviceNo, long bindingId, int expectedVersion) {
        return jdbc.update("UPDATE tail_device SET current_binding_id = NULL, version = version + 1,"
                        + " updated_at = CURRENT_TIMESTAMP"
                        + " WHERE device_no = ? AND current_binding_id = ? AND version = ?",
                deviceNo, bindingId, expectedVersion) > 0;
    }

    /**
     * 自检换发：更新截止时刻并递增版本，仅当版本匹配时成功。
     *
     * @return 是否换发成功
     */
    public boolean renewSelfCheck(String deviceNo, Instant selfCheckExpiresAt, int expectedVersion) {
        return jdbc.update("UPDATE tail_device SET self_check_expires_at = ?, version = version + 1,"
                        + " updated_at = CURRENT_TIMESTAMP WHERE device_no = ? AND version = ?",
                Timestamp.valueOf(LocalDateTime.ofInstant(selfCheckExpiresAt, ZoneOffset.UTC)),
                deviceNo, expectedVersion) > 0;
    }
}

