                    : rs.getTimestamp("released_at").toLocalDateTime().toInstant(ZoneOffset.UTC));

    private final JdbcTemplate jdbc;

    public TailBindingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 写入绑定记录（ACTIVE）。
     */
    public long insert(long jobId, String deviceNo, int consistVersion, String tailCarNo,
                       Instant selfCheckExpiresAt, String requestId, Instant boundAt) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO tail_device_binding (job_id, device_no, consist_version, tail_car_no,"
                            + " self_check_expires_at, status, request_id, bound_at, released_at)"
                            + " VALUES (?, ?, ?, ?, ?, 'ACTIVE', ?, ?, NULL)",
