            ps.setString(2, deviceNo);
            ps.setInt(3, consistVersion);
            ps.setString(4, tailCarNo);
            ps.setTimestamp(5, Timestamp.valueOf(LocalDateTime.ofInstant(selfCheckExpiresAt, ZoneOffset.UTC)));
            ps.setString(6, requestId);
            ps.setTimestamp(7, Timestamp.valueOf(LocalDateTime.ofInstant(boundAt, ZoneOffset.UTC)));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

