    public void release(long bindingId, TailBindingStatus status, Instant releasedAt) {
        jdbc.update("UPDATE tail_device_binding SET status = ?, released_at = ? WHERE id = ?",
                status.name(),
                Timestamp.valueOf(LocalDateTime.ofInstant(releasedAt, ZoneOffset.UTC)), bindingId);
    }
}

