    }
    if (job.status() != JobStatus.DEPARTURE_CONFIRMED) {
        throw new BusinessException("未发车确认，不得销记：" + job.status());
    }
    jobRepository.close(jobId);
    // 销记才原子解除列尾装置占用并保留全部绑定历史（同事务）
    tailControlService.onJobClosed(jobId);
