/**
 * 列尾证据查询：绑定历史与一致性确认全量留痕。
 */
@Transactional(readOnly = true)
public TailEvidenceResponse getEvidence(long jobId) {
    jobRepository.findById(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    List<TailEvidenceResponse.BindingView> bindings = bindingRepository.findByJobId(jobId).stream()
            .map(b -> new TailEvidenceResponse.BindingView(b.id(), b.deviceNo(), b.consistVersion(),
                    b.tailCarNo(), b.selfCheckExpiresAt(), b.status().name(), b.boundAt(), b.releasedAt(),
                    confirmationRepository.findByBindingId(b.id()).stream()
                            .map(c -> new TailEvidenceResponse.ConfirmationView(c.id(), c.consistVersion(),
                                    c.tailCarNo(), c.confirmer1(), c.confirmer2(), c.valid(), c.createdAt()))
                            .toList()))
            .toList();
    return new TailEvidenceResponse(jobId, !bindings.isEmpty(), bindings);
}

/**
 * 摘挂变更联动：作业当前 ACTIVE 绑定的一致性确认立即失效（同事务调用）。
 */
public void onConsistChanged(long jobId) {
    bindingRepository.findActiveByJobId(jobId)
            .ifPresent(binding -> confirmationRepository.invalidateByBindingId(binding.id()));
}

/**
 * 发车确认联动：受控作业须装置自检未过期且一致性确认匹配最新编组（同事务调用）。
 * 未启用列尾控制的历史作业不增加新门禁。
 *
 * @param job 已加锁的作业行
 */
public void checkDepartureGate(JobRow job) {
    Optional<TailBindingRow> active = bindingRepository.findActiveByJobId(job.id());
    if (active.isEmpty()) {
        return;
    }
    TailBindingRow binding = active.get();
    TailDeviceRow device = deviceRepository.findByDeviceNo(binding.deviceNo())
            .orElseThrow(() -> new IllegalStateException("绑定装置台账缺失：" + binding.deviceNo()));
    if (!timeSource.now().isBefore(device.selfCheckExpiresAt())) {
        throw new BusinessException("列尾装置自检已过期，拒绝发车：" + device.deviceNo());
    }
    TailConfirmationRow confirmation = confirmationRepository.findValidByBindingId(binding.id())
            .orElseThrow(() -> new BusinessException("尾车一致性确认缺失或已失效，拒绝发车"));
    if (confirmation.consistVersion() != job.consistVersion()) {
        throw new BusinessException("一致性确认编组版本与最新编组不一致，拒绝发车");
    }
    String tailCarNo = currentTailCarNo(job.id());
    if (!confirmation.tailCarNo().equals(tailCarNo)) {
        throw new BusinessException("一致性确认尾车与当前编组尾车不一致，拒绝发车");
    }
}

/**
 * 销记联动：原子解除装置占用并保留全部绑定历史（同事务调用）。
 */
public void onJobClosed(long jobId) {
    bindingRepository.findActiveByJobId(jobId).ifPresent(binding -> {
        TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(binding.deviceNo())
                .orElseThrow(() -> new IllegalStateException("绑定装置台账缺失：" + binding.deviceNo()));
        confirmationRepository.invalidateByBindingId(binding.id());
        bindingRepository.release(binding.id(), TailBindingStatus.RELEASED_CLOSED, timeSource.now());
        if (!deviceRepository.release(device.deviceNo(), binding.id(), device.version())) {
            throw new IllegalStateException("销记释放装置占用失败：" + device.deviceNo());
        }
    });
}

private TailDeviceResponse doRegisterDevice(TailDeviceRegisterRequest request) {
    if (!request.selfCheckExpiresAt().isAfter(timeSource.now())) {
        throw new BusinessException("自检合格有效截止时刻须晚于当前UTC时刻");
    }
    try {
        deviceRepository.insert(request.deviceNo(), request.selfCheckExpiresAt());
    } catch (DuplicateKeyException e) {
        throw new ConflictException("列尾装置编号已存在：" + request.deviceNo());
    }
    return toDeviceResponse(deviceRepository.findByDeviceNo(request.deviceNo()).orElseThrow());
}

private TailDeviceResponse doRenewSelfCheck(String deviceNo, TailSelfCheckRenewRequest request) {
    TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(deviceNo)
            .orElseThrow(() -> new NotFoundException("列尾装置不存在：" + deviceNo));
    if (device.version() != request.expectedVersion()) {
        throw new ConflictException("装置版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + device.version());
    }
    if (!request.selfCheckExpiresAt().isAfter(timeSource.now())) {
        throw new BusinessException("自检合格有效截止时刻须晚于当前UTC时刻");
    }
    if (!deviceRepository.renewSelfCheck(deviceNo, request.selfCheckExpiresAt(),
            request.expectedVersion())) {
        throw new ConflictException("装置版本并发变更，换发失败：" + deviceNo);
    }
    return toDeviceResponse(deviceRepository.findByDeviceNo(deviceNo).orElseThrow());
}

private TailBindResponse doBind(long jobId, TailBindRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("当前状态不允许绑定列尾装置：" + job.status());
    }
    if (bindingRepository.findActiveByJobId(jobId).isPresent()) {
        throw new BusinessException("作业已绑定列尾装置，须先解除：" + jobId);
    }
    TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(request.deviceNo())
            .orElseThrow(() -> new NotFoundException("列尾装置不存在：" + request.deviceNo()));
    if (device.version() != request.expectedVersion()) {
        throw new ConflictException("装置版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + device.version());
    }
    Instant now = timeSource.now();
    if (!now.isBefore(device.selfCheckExpiresAt())) {
        throw new BusinessException("列尾装置自检不合格或已过期，拒绝绑定：" + request.deviceNo());
    }
    String tailCarNo = currentTailCarNo(jobId);
    long bindingId = bindingRepository.insert(jobId, device.deviceNo(), job.consistVersion(),
            tailCarNo, device.selfCheckExpiresAt(), request.requestId(), now);
    if (!deviceRepository.occupy(device.deviceNo(), bindingId, device.version())) {
        throw new ConflictException("列尾装置已被占用，并发绑定冲突：" + request.deviceNo());
    }
    return new TailBindResponse(bindingId, jobId, device.deviceNo(), job.consistVersion(),
            tailCarNo, device.version() + 1, now, "列尾装置绑定成功，编组版本已冻结");
}

private TailConfirmResponse doConfirm(long jobId, TailConfirmRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("当前状态不允许尾车一致性确认：" + job.status());
    }
    TailBindingRow binding = requireActiveBinding(jobId);
    if (job.consistVersion() != request.expectedVersion()) {
        throw new ConflictException("编组版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + job.consistVersion());
    }
    if (request.confirmer1().equals(request.confirmer2())) {
        throw new BusinessException("尾车一致性确认须由两名不同人员共同确认");
    }
    String tailCarNo = currentTailCarNo(jobId);
    if (!request.tailCarNo().equals(tailCarNo)) {
        throw new BusinessException("确认尾车与当前编组尾车不一致：" + request.tailCarNo());
    }
    // 重新确认：同绑定下旧确认同事务失效，仅最新一条有效
    confirmationRepository.invalidateByBindingId(binding.id());
    long confirmationId = confirmationRepository.insert(binding.id(), jobId, job.consistVersion(),
            tailCarNo, request.confirmer1(), request.confirmer2(), request.requestId());
    return new TailConfirmResponse(confirmationId, binding.id(), job.consistVersion(),
            tailCarNo, "尾车一致性确认完成");
}

private TailUnbindResponse doUnbind(long jobId, TailUnbindRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("受控作业仅允许发车确认前提前解绑：" + job.status());
    }
    TailBindingRow binding = requireActiveBinding(jobId);
    TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(binding.deviceNo())
            .orElseThrow(() -> new IllegalStateException("绑定装置台账缺失：" + binding.deviceNo()));
    if (device.version() != request.expectedVersion()) {
        throw new ConflictException("装置版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + device.version());
    }
    Instant now = timeSource.now();
    // 解绑同时撤销一致性确认，保留全部历史
    confirmationRepository.invalidateByBindingId(binding.id());
    bindingRepository.release(binding.id(), TailBindingStatus.RELEASED_EARLY, now);
    if (!deviceRepository.release(device.deviceNo(), binding.id(), device.version())) {
        throw new ConflictException("装置版本并发变更，解绑失败：" + device.deviceNo());
    }
    return new TailUnbindResponse(binding.id(), device.deviceNo(), device.version() + 1, now,
            "列尾装置已提前解绑，一致性确认已撤销");
}

