private TailBindResponse doBind(long jobId, TailBindRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("当前状态不允许绑定列尾装置：" + job.status());
    }
    if (bindingRepository.findActiveByJobId(jobId).isPresent()) {
        throw new BusinessException("作业已绑定列尾装置，须先解除：" + jobId);
    }
    TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(request.deviceNo())
            .orElseThrow(() -> new NotFoundException("列尾装置不存在：" + request.deviceNo()));
    if (device.version() != request.expectedVersion()) {
        throw new ConflictException("装置版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + device.version());
    }
    Instant now = timeSource.now();
    if (!now.isBefore(device.selfCheckExpiresAt())) {
        throw new BusinessException("列尾装置自检不合格或已过期，拒绝绑定：" + request.deviceNo());
    }
    String tailCarNo = currentTailCarNo(jobId);
    long bindingId = bindingRepository.insert(jobId, device.deviceNo(), job.consistVersion(),
            tailCarNo, device.selfCheckExpiresAt(), request.requestId(), now);
    if (!deviceRepository.occupy(device.deviceNo(), bindingId, device.version())) {
        throw new ConflictException("列尾装置已被占用，并发绑定冲突：" + request.deviceNo());
    }
    return new TailBindResponse(bindingId, jobId, device.deviceNo(), job.consistVersion(),
            tailCarNo, device.version() + 1, now, "列尾装置绑定成功，编组版本已冻结");
}

private TailConfirmResponse doConfirm(long jobId, TailConfirmRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("当前状态不允许尾车一致性确认：" + job.status());
    }
    TailBindingRow binding = requireActiveBinding(jobId);
    if (job.consistVersion() != request.expectedVersion()) {
        throw new ConflictException("编组版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + job.consistVersion());
    }
    if (request.confirmer1().equals(request.confirmer2())) {
        throw new BusinessException("尾车一致性确认须由两名不同人员共同确认");
    }
    String tailCarNo = currentTailCarNo(jobId);
    if (!request.tailCarNo().equals(tailCarNo)) {
        throw new BusinessException("确认尾车与当前编组尾车不一致：" + request.tailCarNo());
    }
    // 重新确认：同绑定下旧确认同事务失效，仅最新一条有效
    confirmationRepository.invalidateByBindingId(binding.id());
    long confirmationId = confirmationRepository.insert(binding.id(), jobId, job.consistVersion(),
            tailCarNo, request.confirmer1(), request.confirmer2(), request.requestId());
    return new TailConfirmResponse(confirmationId, binding.id(), job.consistVersion(),
            tailCarNo, "尾车一致性确认完成");
}

private TailUnbindResponse doUnbind(long jobId, TailUnbindRequest request) {
    JobRow job = jobRepository.findByIdForUpdate(jobId)
            .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
    if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
        throw new BusinessException("受控作业仅允许发车确认前提前解绑：" + job.status());
    }
    TailBindingRow binding = requireActiveBinding(jobId);
    TailDeviceRow device = deviceRepository.findByDeviceNoForUpdate(binding.deviceNo())
            .orElseThrow(() -> new IllegalStateException("绑定装置台账缺失：" + binding.deviceNo()));
    if (device.version() != request.expectedVersion()) {
        throw new ConflictException("装置版本不一致：期望 " + request.expectedVersion()
                + "，当前 " + device.version());
    }
    Instant now = timeSource.now();
    // 解绑同时撤销一致性确认，保留全部历史
    confirmationRepository.invalidateByBindingId(binding.id());
    bindingRepository.release(binding.id(), TailBindingStatus.RELEASED_EARLY, now);
    if (!deviceRepository.release(device.deviceNo(), binding.id(), device.version())) {
        throw new ConflictException("装置版本并发变更，解绑失败：" + device.deviceNo());
    }
    return new TailUnbindResponse(binding.id(), device.deviceNo(), device.version() + 1, now,
            "列尾装置已提前解绑，一致性确认已撤销");
}

