import com.example.starter.web.dto.TailSelfCheckRenewRequest;
import com.example.starter.web.dto.TailUnbindRequest;
import com.example.starter.web.dto.TailUnbindResponse;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 列尾装置绑定与尾车一致性校验服务。
 * 规则：受控作业绑定一台空闲装置与当前编组尾车，UTC now 严格小于自检截止才可绑定；
 * 摘挂改变尾车或编组版本时绑定保留但一致性确认立即失效，须两名不同人员重新确认；
 * 发车确认同事务检查制动试验有效、装置自检未过期、一致性确认匹配最新编组；
 * 销记才原子解除装置占用并保留全部绑定历史；提前解绑仅允许发车前并同时撤销确认。
 */
@Service
public class TailControlService {

    private final TailDeviceRepository deviceRepository;
    private final TailBindingRepository bindingRepository;
    private final TailConfirmationRepository confirmationRepository;
    private final TrainJobRepository jobRepository;
    private final TrainCarRepository carRepository;
    private final IdempotencyService idempotencyService;
    private final TimeSource timeSource;

    public TailControlService(TailDeviceRepository deviceRepository,
                              TailBindingRepository bindingRepository,
                              TailConfirmationRepository confirmationRepository,
                              TrainJobRepository jobRepository,
                              TrainCarRepository carRepository,
                              IdempotencyService idempotencyService,
                              TimeSource timeSource) {
        this.deviceRepository = deviceRepository;
        this.bindingRepository = bindingRepository;
        this.confirmationRepository = confirmationRepository;
        this.jobRepository = jobRepository;
        this.carRepository = carRepository;
        this.idempotencyService = idempotencyService;
        this.timeSource = timeSource;
    }

    /**
     * 装置建档：编号唯一，初始版本1。
     */
    public TailDeviceResponse registerDevice(TailDeviceRegisterRequest request) {
        return idempotencyService.execute(request.requestId(), "TAIL_DEVICE_REGISTER", request,
                TailDeviceResponse.class, () -> doRegisterDevice(request));
    }

    /**
     * 自检换发：更新有效截止时刻并递增版本。
     */
    public TailDeviceResponse renewSelfCheck(String deviceNo, TailSelfCheckRenewRequest request) {
        return idempotencyService.execute(request.requestId(), "TAIL_SELF_CHECK", request,
                TailDeviceResponse.class, () -> doRenewSelfCheck(deviceNo, request));
    }

    /**
     * 绑定：受控作业绑定空闲装置与当前编组尾车，冻结编组版本。
     */
    public TailBindResponse bind(long jobId, TailBindRequest request) {
        return idempotencyService.execute(request.requestId(), "TAIL_BIND", request,
                TailBindResponse.class, () -> doBind(jobId, request));
    }

    /**
     * 一致性确认：两名不同人员共同确认新尾车及编组版本。
     */
    public TailConfirmResponse confirm(long jobId, TailConfirmRequest request) {
        return idempotencyService.execute(request.requestId(), "TAIL_CONFIRM", request,
                TailConfirmResponse.class, () -> doConfirm(jobId, request));
    }

    /**
     * 提前解绑：仅允许发车确认前，解绑同时撤销一致性确认。
     */
    public TailUnbindResponse unbind(long jobId, TailUnbindRequest request) {
        return idempotencyService.execute(request.requestId(), "TAIL_UNBIND", request,
                TailUnbindResponse.class, () -> doUnbind(jobId, request));
    }

    /**
     * 装置查询。
     */
    @Transactional(readOnly = true)
    public TailDeviceResponse getDevice(String deviceNo) {
        TailDeviceRow device = deviceRepository.findByDeviceNo(deviceNo)
                .orElseThrow(() -> new NotFoundException("列尾装置不存在：" + deviceNo));
        return toDeviceResponse(device);
    }

    /**
     * 列尾证据查询：绑定历史与一致性确认全量留痕。
     */
    @Transactional(readOnly = true)
    public TailEvidenceResponse getEvidence(long jobId) {
        throw new UnsupportedOperationException("待实现");
    }

    /**
     * 摘挂变更联动：作业当前 ACTIVE 绑定的一致性确认立即失效（同事务调用）。
     */
    public void onConsistChanged(long jobId) {
        bindingRepository.findActiveByJobId(jobId)
                .ifPresent(binding -> confirmationRepository.invalidateByBindingId(binding.id()));
    }

    /**
     * 发车确认联动：受控作业须装置自检未过期且一致性确认匹配最新编组（同事务调用）。
     *
     * @param job 已加锁的作业行
     */
    public void checkDepartureGate(JobRow job) {
        throw new UnsupportedOperationException("待实现");
    }

    /**
     * 销记联动：原子解除装置占用并保留全部绑定历史（同事务调用）。
     */
    public void onJobClosed(long jobId) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailDeviceResponse doRegisterDevice(TailDeviceRegisterRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailDeviceResponse doRenewSelfCheck(String deviceNo, TailSelfCheckRenewRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailBindResponse doBind(long jobId, TailBindRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailConfirmResponse doConfirm(long jobId, TailConfirmRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailUnbindResponse doUnbind(long jobId, TailUnbindRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    private TailDeviceResponse toDeviceResponse(TailDeviceRow device) {
        return new TailDeviceResponse(device.deviceNo(), device.selfCheckExpiresAt(),
                device.currentBindingId(), device.version());
    }

    @SuppressWarnings("unused")
    private TailBindingRow requireActiveBinding(long jobId) {
        return bindingRepository.findActiveByJobId(jobId)
                .orElseThrow(() -> new BusinessException("作业无绑定中的列尾装置：" + jobId));
    }
}

