package com.example.starter.service;

import com.example.starter.domain.TailBindingStatus;
import com.example.starter.repo.TailBindingRow;
import com.example.starter.repo.TailDeviceRepository;
import com.example.starter.repo.TailDeviceRow;
import com.example.starter.web.dto.AcceptJobRequest;
import com.example.starter.web.dto.BrakeTestRequest;
import com.example.starter.web.dto.CarDto;
import com.example.starter.web.dto.ConsistChangeRequest;
import com.example.starter.web.dto.ConsistCheckRequest;
import com.example.starter.web.dto.ConsistCheckResponse;
import com.example.starter.web.dto.DepartureResponse;
import com.example.starter.web.dto.JobResponse;
import com.example.starter.web.dto.RequestIdOnly;
import com.example.starter.web.dto.TailBindRequest;
import com.example.starter.web.dto.TailBindResponse;
import com.example.starter.web.dto.TailConfirmRequest;
import com.example.starter.web.dto.TailConfirmResponse;
import com.example.starter.web.dto.TailDeviceRegisterRequest;
import com.example.starter.web.dto.TailDeviceResponse;
import com.example.starter.web.dto.TailEvidenceResponse;
import com.example.starter.web.dto.TailSelfCheckRenewRequest;
import com.example.starter.web.dto.TailUnbindRequest;
import com.example.starter.web.dto.TailUnbindResponse;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 列尾装置绑定与尾车一致性校验服务测试（H2 内存库 MySQL 兼容模式，真实事务、约束与并发）。
 */
@SpringBootTest(properties = "spring.datasource.url=jdbc:h2:mem:test_tail_demo;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TailControlServiceTest {

    private static final Instant FIXED_NOW = Instant.parse("2026-09-27T02:00:00Z");

    @Autowired
    private TrainJobService jobService;

    @Autowired
    private TailControlService tailService;

    @Autowired
    private TailDeviceRepository deviceRepository;

    @Autowired
    private TimeSource timeSource;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        timeSource.setClock(Clock.fixed(FIXED_NOW, ZoneOffset.UTC));
        jdbc.update("DELETE FROM tail_consistency_confirmation");
        jdbc.update("DELETE FROM tail_device_binding");
        jdbc.update("DELETE FROM tail_device");
        jdbc.update("DELETE FROM idempotency_record");
        jdbc.update("DELETE FROM late_event");
        jdbc.update("DELETE FROM pressure_reading");
        jdbc.update("DELETE FROM brake_test");
        jdbc.update("DELETE FROM consist_check");
        jdbc.update("DELETE FROM train_car");
        jdbc.update("DELETE FROM train_job");
    }

    @AfterEach
    void resetClock() {
        timeSource.setClock(Clock.systemUTC());
    }

    @AfterAll
    void releaseDatabase() {
        jdbc.execute("SHUTDOWN");
    }

    private List<CarDto> cars(int total) {
        List<CarDto> cars = new ArrayList<>();
        for (int i = 1; i <= total; i++) {
            cars.add(new CarDto("C" + i, new BigDecimal("80.0"), new BigDecimal("1.3"), false));
        }
        return cars;
    }

    private long acceptJob(String key, String track, int total) {
        return jobService.accept(new AcceptJobRequest(key, "T" + key, track, cars(total))).id();
    }

    private JobResponse acceptAndCheck(String key, String track, int total) {
        long jobId = acceptJob(key + "-a", track, total);
        ConsistCheckResponse check = jobService.checkConsist(jobId, new ConsistCheckRequest(
                key + "-c", total, new BigDecimal("1.3").multiply(BigDecimal.valueOf(total)),
                new BigDecimal("80.0").multiply(BigDecimal.valueOf(total))));
        assertTrue(check.matched());
        return jobService.getJob(jobId);
    }

    private void passBrakeTests(long jobId, String key) {
        jobService.brakeTest(jobId, new BrakeTestRequest(key + "-s",
                com.example.starter.domain.TestType.SENSITIVITY, 50, 500, true, null));
        jobService.brakeTest(jobId, new BrakeTestRequest(key + "-t",
                com.example.starter.domain.TestType.STABILITY, 140, 500, null, false));
    }

    private TailDeviceResponse registerDevice(String key, String deviceNo, Instant expiresAt) {
        return tailService.registerDevice(
                new TailDeviceRegisterRequest(key, deviceNo, expiresAt));
    }

    /** 受控作业走完全部门禁至发车确认。 */
    private long fullyPreparedControlledJob(String key, String track, int total, Instant expiresAt) {
        JobResponse job = acceptAndCheck(key, track, total);
        registerDevice(key + "-dev", "D-" + key, expiresAt);
        TailBindResponse bind = tailService.bind(job.id(),
