    @Test
    void 同一装置并发绑定唯一成功() throws Exception {
        long job1 = acceptJob("r11-a1", "T11a", 10);
        long job2 = acceptJob("r11-a2", "T11b", 10);
        registerDevice("r11-dev", "D11", Instant.parse("2026-09-27T03:00:00Z"));

        int threads = 2;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger success = new AtomicInteger();
        AtomicInteger conflict = new AtomicInteger();
        List<Future<?>> futures = new ArrayList<>();
        long[] jobIds = {job1, job2};
        for (int i = 0; i < threads; i++) {
            int idx = i;
            futures.add(pool.submit(() -> {
                ready.countDown();
                try {
                    start.await(5, TimeUnit.SECONDS);
                    tailService.bind(jobIds[idx],
                            new TailBindRequest("r11-b" + idx, "D11", 1));
                    success.incrementAndGet();
                } catch (ConflictException e) {
                    conflict.incrementAndGet();
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }));
        }
        assertTrue(ready.await(5, TimeUnit.SECONDS));
        start.countDown();
        for (Future<?> future : futures) {
            future.get(20, TimeUnit.SECONDS);
        }
        pool.shutdownNow();
        assertEquals(1, success.get());
        assertEquals(1, conflict.get());
        // 仅一条 ACTIVE 绑定，装置仍被唯一作业占用
        Integer activeCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM tail_device_binding WHERE device_no = 'D11' AND status = 'ACTIVE'",
                Integer.class);
        assertEquals(1, activeCount);
        assertNotNull(deviceRepository.findByDeviceNo("D11").orElseThrow().currentBindingId());
    }

