        registerDevice("r12-dev", "D12", Instant.parse("2026-09-27T03:00:00Z"));
        tailService.bind(job.id(), new TailBindRequest("r12-b", "D12", 1));
        TailConfirmResponse confirm = tailService.confirm(job.id(),
                new TailConfirmRequest("r12-c", 1, "C10", "u1", "u2"));
        assertEquals(1, confirm.consistVersion());

        // 同一人不可确认
        BusinessException samePerson = assertThrows(BusinessException.class,
                () -> tailService.confirm(job.id(),
                        new TailConfirmRequest("r12-csame", 1, "C10", "u1", "u1")));
        assertTrue(samePerson.getMessage().contains("两名不同人员"));

        // 尾车不匹配拒绝
        assertThrows(BusinessException.class,
                () -> tailService.confirm(job.id(),
                        new TailConfirmRequest("r12-cwrong", 1, "C9", "u1", "u2")));

        // 摘掉尾车并挂新车：尾车变为 C11，编组版本变为2，绑定保留
        jobService.changeConsist(job.id(), new ConsistChangeRequest(
                "r12-g", List.of(new CarDto("C11", new BigDecimal("80.0"), new BigDecimal("1.3"), false)),
                List.of("C10")));
        // 旧确认已失效
        TailEvidenceResponse evidence = tailService.getEvidence(job.id());
        assertFalse(evidence.bindings().get(0).confirmations().get(0).valid());
        assertEquals(TailBindingStatus.ACTIVE.name(), evidence.bindings().get(0).status());

        // 旧版本确认 409
        assertThrows(ConflictException.class,
                () -> tailService.confirm(job.id(),
                        new TailConfirmRequest("r12-c2old", 1, "C11", "u1", "u2")));
        // 新尾车新版本两人确认成功
        TailConfirmResponse reconfirmed = tailService.confirm(job.id(),
                new TailConfirmRequest("r12-c2", 2, "C11", "u1", "u2"));
        assertEquals(2, reconfirmed.consistVersion());
        assertEquals("C11", reconfirmed.tailCarNo());
    }

