import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 列尾装置绑定与编组变更发车联锁 API 测试（MockMvc + H2）。
 */
@SpringBootTest(properties = "spring.datasource.url=jdbc:h2:mem:test_tail_web_demo;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1")
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TailControlApiTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        jdbc.update("DELETE FROM tail_consistency_confirmation");
        jdbc.update("DELETE FROM tail_device_binding");
        jdbc.update("DELETE FROM tail_device");
        jdbc.update("DELETE FROM idempotency_record");
        jdbc.update("DELETE FROM late_event");
        jdbc.update("DELETE FROM pressure_reading");
        jdbc.update("DELETE FROM brake_test");
        jdbc.update("DELETE FROM consist_check");
        jdbc.update("DELETE FROM train_car");
        jdbc.update("DELETE FROM train_job");
    }

    @AfterAll
    void releaseDatabase() {
        jdbc.execute("SHUTDOWN");
    }

    private StringBuilder carsJson() {
        StringBuilder cars = new StringBuilder();
        for (int i = 1; i <= 10; i++) {
            if (i > 1) {
                cars.append(',');
            }
            cars.append("{\"carNo\":\"C").append(i)
                    .append("\",\"weightTons\":80.0,\"length\":1.3,\"valveClosed\":false}");
        }
        return cars;
    }

    private long acceptJob(String requestId, String track) throws Exception {
        String body = "{\"requestId\":\"" + requestId + "\",\"trainNo\":\"T1\",\"track\":\"" + track
                + "\",\"cars\":[" + carsJson() + "]}";
        MvcResult result = mockMvc.perform(post("/api/jobs")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn();
        return Long.parseLong(result.getResponse().getContentAsString()
                .replaceAll(".*\"id\":(\\d+).*", "$1"));
    }

    private long registerDevice(String requestId, String deviceNo, String expiresAt) throws Exception {
        mockMvc.perform(post("/api/tail-devices")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"" + requestId + "\",\"deviceNo\":\"" + deviceNo
                                + "\",\"selfCheckExpiresAt\":\"" + expiresAt + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.version", is(1)));
        return 1;
    }

    private void checkConsist(long jobId, String requestId, int count) throws Exception {
        mockMvc.perform(post("/api/jobs/{id}/consist-checks", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"" + requestId + "\",\"expectedCarCount\":" + count + ","
                                + "\"expectedTotalLength\":13.0,\"expectedTotalWeight\":800.0}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.matched", is(true)));
    }

    @Test
    void 列尾受控主流程绑定确认发车销记() throws Exception {
        long jobId = acceptJob("t1-a", "TW1");
        checkConsist(jobId, "t1-c", 10);
        registerDevice("t1-dev", "TD1", "2099-01-01T00:00:00Z");

        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-b\",\"deviceNo\":\"TD1\",\"expectedVersion\":1}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.consistVersion", is(1)))
                .andExpect(jsonPath("$.tailCarNo", is("C10")))
                .andExpect(jsonPath("$.deviceVersion", is(2)));

        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-cf\",\"expectedVersion\":1,\"tailCarNo\":\"C10\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u2\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.consistVersion", is(1)));

        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-s\",\"testType\":\"SENSITIVITY\","
                                + "\"pressureReduction\":50,\"pipePressureBefore\":500,"
                                + "\"allCarsBraked\":true}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-t\",\"testType\":\"STABILITY\","
                                + "\"pressureReduction\":140,\"pipePressureBefore\":500,"
                                + "\"emergencyOccurred\":false}"))
                .andExpect(status().isOk());

        mockMvc.perform(post("/api/jobs/{id}/departure-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-d\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.approved", is(true)));

        mockMvc.perform(post("/api/jobs/{id}/closures", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t1-x\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/api/tail-devices/TD1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.currentBindingId").doesNotExist())
                .andExpect(jsonPath("$.version", is(3)));

        mockMvc.perform(get("/api/jobs/{id}/tail-evidence", jobId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.tailControlled", is(true)))
                .andExpect(jsonPath("$.bindings.length()", is(1)))
                .andExpect(jsonPath("$.bindings[0].status", is("RELEASED_CLOSED")))
                .andExpect(jsonPath("$.bindings[0].confirmations[0].valid", is(false)));
    }

    @Test
    void 摘挂后旧确认失效发车422重新确认后放行() throws Exception {
        long jobId = acceptJob("t2-a", "TW2");
        checkConsist(jobId, "t2-c", 10);
        registerDevice("t2-dev", "TD2", "2099-01-01T00:00:00Z");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-b\",\"deviceNo\":\"TD2\",\"expectedVersion\":1}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-cf\",\"expectedVersion\":1,\"tailCarNo\":\"C10\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u2\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-s\",\"testType\":\"SENSITIVITY\","
                                + "\"pressureReduction\":50,\"pipePressureBefore\":500,"
                                + "\"allCarsBraked\":true}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-t\",\"testType\":\"STABILITY\","
                                + "\"pressureReduction\":140,\"pipePressureBefore\":500,"
                                + "\"emergencyOccurred\":false}"))
                .andExpect(status().isOk());

        // 摘掉尾车 C10、挂 C11：版本2、尾车C11，旧确认失效
        mockMvc.perform(post("/api/jobs/{id}/consist-changes", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-g\",\"attachCars\":[{\"carNo\":\"C11\","
                                + "\"weightTons\":80.0,\"length\":1.3,\"valveClosed\":false}],"
                                + "\"detachCarNos\":[\"C10\"]}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.consistVersion", is(2)));

        mockMvc.perform(post("/api/jobs/{id}/departure-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-d1\"}"))
                .andExpect(status().isUnprocessableEntity());

        // 用旧版本重新确认：409
        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-cfold\",\"expectedVersion\":1,\"tailCarNo\":\"C11\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u2\"}"))
                .andExpect(status().isConflict());

        // 重新核对编组，两人确认新尾车新版本，重做试验后放行
        checkConsist(jobId, "t2-c2", 10);
        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-cf2\",\"expectedVersion\":2,\"tailCarNo\":\"C11\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u2\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-s2\",\"testType\":\"SENSITIVITY\","
                                + "\"pressureReduction\":50,\"pipePressureBefore\":500,"
                                + "\"allCarsBraked\":true}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-t2\",\"testType\":\"STABILITY\","
                                + "\"pressureReduction\":140,\"pipePressureBefore\":500,"
                                + "\"emergencyOccurred\":false}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/departure-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t2-d2\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.approved", is(true)));
    }

    @Test
    void 未知装置404自检过期422占用冲突409() throws Exception {
        long jobId = acceptJob("t3-a", "TW3");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t3-b\",\"deviceNo\":\"NOPE\",\"expectedVersion\":1}"))
                .andExpect(status().isNotFound());

        registerDevice("t3-dev", "TD3", "2000-01-01T00:00:00Z");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t3-b2\",\"deviceNo\":\"TD3\",\"expectedVersion\":1}"))
                .andExpect(status().isUnprocessableEntity());

        registerDevice("t3-dev2", "TD3B", "2099-01-01T00:00:00Z");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t3-b3\",\"deviceNo\":\"TD3B\",\"expectedVersion\":9}"))
                .andExpect(status().isConflict());
        // 版本冲突未占用装置
        assertEquals(0, jdbc.queryForObject(
                "SELECT COUNT(*) FROM tail_device_binding", Integer.class));
    }

    @Test
    void 同键异参409同键同参重放() throws Exception {
        long jobId = acceptJob("t4-a", "TW4");
        registerDevice("t4-dev", "TD4", "2099-01-01T00:00:00Z");
        String body = "{\"requestId\":\"t4-b\",\"deviceNo\":\"TD4\",\"expectedVersion\":1}";
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated());
        // 重放
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated());
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM tail_device_binding", Integer.class));
        // 异参
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t4-b\",\"deviceNo\":\"TD4\",\"expectedVersion\":2}"))
                .andExpect(status().isConflict());
    }

    @Test
    void 非法参数400() throws Exception {
        long jobId = acceptJob("t5-a", "TW5");
        // expectedVersion 非正数
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t5-b\",\"deviceNo\":\"TD5\",\"expectedVersion\":0}"))
                .andExpect(status().isBadRequest());
        // 建档缺字段
        mockMvc.perform(post("/api/tail-devices")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"deviceNo\":\"TD5\"}"))
                .andExpect(status().isBadRequest());
        // 同一人确认
        registerDevice("t5-dev", "TD5", "2099-01-01T00:00:00Z");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t5-b2\",\"deviceNo\":\"TD5\",\"expectedVersion\":1}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t5-c\",\"expectedVersion\":1,\"tailCarNo\":\"C10\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u1\"}"))
                .andExpect(status().isUnprocessableEntity());
    }

    @Test
    void 证据查询作业不存在404() throws Exception {
        mockMvc.perform(get("/api/jobs/{id}/tail-evidence", 999999))
                .andExpect(status().isNotFound());
        mockMvc.perform(get("/api/tail-devices/NOPE"))
                .andExpect(status().isNotFound());
    }

    @Test
    void 发车后提前解绑422() throws Exception {
        long jobId = acceptJob("t6-a", "TW6");
        checkConsist(jobId, "t6-c", 10);
        registerDevice("t6-dev", "TD6", "2099-01-01T00:00:00Z");
        mockMvc.perform(post("/api/jobs/{id}/tail-bindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-b\",\"deviceNo\":\"TD6\",\"expectedVersion\":1}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/jobs/{id}/tail-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-cf\",\"expectedVersion\":1,\"tailCarNo\":\"C10\","
                                + "\"confirmer1\":\"u1\",\"confirmer2\":\"u2\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-s\",\"testType\":\"SENSITIVITY\","
                                + "\"pressureReduction\":50,\"pipePressureBefore\":500,"
                                + "\"allCarsBraked\":true}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/brake-tests", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-t\",\"testType\":\"STABILITY\","
                                + "\"pressureReduction\":140,\"pipePressureBefore\":500,"
                                + "\"emergencyOccurred\":false}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/departure-confirmations", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-d\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/jobs/{id}/tail-unbindings", jobId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"t6-u\",\"expectedVersion\":2}"))
                .andExpect(status().isUnprocessableEntity());
    }
}

