@Test
void 摘挂与发车竞争保持一致顺序() throws Exception {
    long jobId = fullyPreparedControlledJob("r25", "T25", 10,
            Instant.parse("2026-09-27T03:00:00Z"));
    ExecutorService pool = Executors.newFixedThreadPool(2);
    CountDownLatch ready = new CountDownLatch(2);
    CountDownLatch start = new CountDownLatch(1);
    AtomicInteger departureOk = new AtomicInteger();
    AtomicInteger changeOk = new AtomicInteger();
    Future<?> departureFuture = pool.submit(() -> {
        ready.countDown();
        try {
            start.await(5, TimeUnit.SECONDS);
            jobService.confirmDeparture(jobId, new RequestIdOnly("r25-d"));
            departureOk.incrementAndGet();
        } catch (BusinessException e) {
            // 摘挂先完成：发车被拒
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    Future<?> changeFuture = pool.submit(() -> {
        ready.countDown();
        try {
            start.await(5, TimeUnit.SECONDS);
            jobService.changeConsist(jobId, new ConsistChangeRequest(
                    "r25-g", List.of(new CarDto("C11", new BigDecimal("80.0"),
                            new BigDecimal("1.3"), false)), List.of("C10")));
            changeOk.incrementAndGet();
        } catch (BusinessException e) {
            // 发车先完成：摘挂被拒
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    assertTrue(ready.await(5, TimeUnit.SECONDS));
    start.countDown();
    departureFuture.get(20, TimeUnit.SECONDS);
    changeFuture.get(20, TimeUnit.SECONDS);
    pool.shutdownNow();
    // 作业行锁串行化：恰一个成功，最终状态与之一致
    assertEquals(1, departureOk.get() + changeOk.get());
    JobResponse current = jobService.getJob(jobId);
    if (departureOk.get() == 1) {
        assertEquals("DEPARTURE_CONFIRMED", current.status());
        assertEquals(1, current.consistVersion());
    } else {
        assertEquals("ACCEPTED", current.status());
        assertEquals(2, current.consistVersion());
        // 一致性确认已失效，不得沿用旧结论发车
        assertThrows(BusinessException.class,
                () -> jobService.confirmDeparture(jobId, new RequestIdOnly("r25-d2")));
    }
}

